<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\UserRoleAssignment;
use Civi\Lughauth\Shared\Event\PublicEvent;

class UserRoleAssignmentUpdateEvent extends UserRoleAssignmentEvent implements PublicEvent
{
    public function __construct(
        UserRoleAssignment $payload,
        public readonly UserRoleAssignment $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'user-role-assignment.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
